import { useEffect } from 'react';

const SEO = ({ title = "Shubham Singh", description = "Shubham Singh - Quantitative Researcher Portfolio", image = "/brain.png", url = window.location.href }) => {
  useEffect(() => {
    // Update document title
    document.title = title;

    // Update meta tags
    let metaDescription = document.querySelector('meta[name="description"]');
    if (!metaDescription) {
      metaDescription = document.createElement('meta');
      metaDescription.name = 'description';
      document.head.appendChild(metaDescription);
    }
    metaDescription.content = description;

    let metaImage = document.querySelector('meta[property="og:image"]');
    if (!metaImage) {
      metaImage = document.createElement('meta');
      metaImage.property = 'og:image';
      document.head.appendChild(metaImage);
    }
    metaImage.content = image;

    let metaTitle = document.querySelector('meta[property="og:title"]');
    if (!metaTitle) {
      metaTitle = document.createElement('meta');
      metaTitle.property = 'og:title';
      document.head.appendChild(metaTitle);
    }
    metaTitle.content = title;

    let metaUrl = document.querySelector('meta[property="og:url"]');
    if (!metaUrl) {
      metaUrl = document.createElement('meta');
      metaUrl.property = 'og:url';
      document.head.appendChild(metaUrl);
    }
    metaUrl.content = url;

    // Twitter card meta tags
    let twitterTitle = document.querySelector('meta[name="twitter:title"]');
    if (!twitterTitle) {
      twitterTitle = document.createElement('meta');
      twitterTitle.name = 'twitter:title';
      document.head.appendChild(twitterTitle);
    }
    twitterTitle.content = title;

    let twitterDescription = document.querySelector('meta[name="twitter:description"]');
    if (!twitterDescription) {
      twitterDescription = document.createElement('meta');
      twitterDescription.name = 'twitter:description';
      document.head.appendChild(twitterDescription);
    }
    twitterDescription.content = description;

    let twitterImage = document.querySelector('meta[name="twitter:image"]');
    if (!twitterImage) {
      twitterImage = document.createElement('meta');
      twitterImage.name = 'twitter:image';
      document.head.appendChild(twitterImage);
    }
    twitterImage.content = image;

    return () => {
      // Cleanup function if needed
    };
  }, [title, description, image, url]);

  return null;
};

export default SEO;
